const body = $input.first().json.body;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

if (message.type !== 'text') {
  return [{ json: {
    skip: false,
    isUnsupported: true,
    phoneNumber: message.from,
    phoneNumberId: change.metadata.phone_number_id,
    response: 'I can only process text messages. Please type your timetable query.\n\nExample: Monday schedule for Sec SD'
  }}];
}

return [{ json: {
  skip: false,
  isUnsupported: false,
  phoneNumber: message.from,
  messageId: message.id,
  query: message.text.body,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
  phoneNumberId: change.metadata.phone_number_id
}}];

const input = $input.first().json;
const query = (input.query || '').trim();
const queryLower = query.toLowerCase();

const validSections = [
  'A','B','C','D','E','F','G','H','I','J','K','L','M','N','O','P','R','S',
  'SA','SB','SC','SD','SE','SF','SG','SH','SI','SJ','SK','SL','SM'
];

let detectedSection = null;
let detectedSectionName = null;

const secMatch = queryLower.match(/(?:sec(?:tion)?[\s-]*)([a-z]{1,2})\b/);
if (secMatch) {
  const letter = secMatch[1].toUpperCase();
  if (validSections.includes(letter)) {
    detectedSection = `Sec-${letter}`;
    detectedSectionName = `Section ${letter}`;
  }
}

const dayMap = {
  'mon': 'Monday', 'monday': 'Monday',
  'tue': 'Tuesday', 'tuesday': 'Tuesday',
  'wed': 'Wednesday', 'wednesday': 'Wednesday',
  'thu': 'Thursday', 'thursday': 'Thursday',
  'fri': 'Friday', 'friday': 'Friday',
  'sat': 'Saturday', 'saturday': 'Saturday'
};

let detectedDay = null;
const now = new Date();
const todayWords = ['today', 'aaj'];
const tomorrowWords = ['tomorrow', 'kal'];

if (todayWords.some(w => queryLower.includes(w))) {
  detectedDay = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][now.getDay()];
} else if (tomorrowWords.some(w => queryLower.includes(w))) {
  const t = new Date(now); t.setDate(t.getDate() + 1);
  detectedDay = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][t.getDay()];
} else {
  for (const [k, v] of Object.entries(dayMap)) {
    if (queryLower.includes(k)) { detectedDay = v; break; }
  }
}

return [{ json: {
  ...input,
  originalQuery: query,
  detectedSection,
  detectedSectionName,
  detectedDay,
  needsSection: !detectedSection,
  needsDay: !detectedDay
}}];

