const rows = $input.all().map(i => i.json);
const preprocessed = $('Query Preprocessor').first().json;
const requestedDay = preprocessed.detectedDay;

const slots = [
  { col: 'Lecture 1 (8.00-8.50)', time: '8:00-8:50 AM' },
  { col: 'Lecture 2 (8.50-9.40)', time: '8:50-9:40 AM' },
  { col: 'Lecture 3 (9.40-10.30)', time: '9:40-10:30 AM' },
  { col: 'Lecture 4 (10.30-11.20)', time: '10:30-11:20 AM' },
  { col: 'Lecture 5 (11.20-12.05)', time: '11:20-12:05 PM' },
  { col: 'Lecture 6 (12.05-12.50)', time: '12:05-12:50 PM' }
];

function formatDaySchedule(row) {
  const day = row['Day/Time'] || '';
  let lines = [`\ud83d\udcc5 *${day}*`];
  for (const slot of slots) {
    const val = (row[slot.col] || '').trim();
    if (val && val !== 'N/A') {
      lines.push(`\u23f0 ${slot.time}\n   \ud83d\udcda ${val}`);
    } else {
      lines.push(`\u23f0 ${slot.time}\n   Free Period`);
    }
  }
  return lines.join('\n');
}

let formatted = [];
if (requestedDay) {
  const dayRow = rows.find(r => r['Day/Time'] && r['Day/Time'].toLowerCase() === requestedDay.toLowerCase());
  if (dayRow) {
    formatted.push(formatDaySchedule(dayRow));
  } else {
    formatted.push(`No schedule found for ${requestedDay}.`);
  }
} else {
  for (const row of rows) {
    if (row['Day/Time'] && row['Day/Time'] !== 'Day/Time') {
      formatted.push(formatDaySchedule(row));
    }
  }
}

const header = preprocessed.detectedSectionName
  ? `\ud83c\udfeb JECRC Timetable\n${preprocessed.detectedSectionName}\n${'\u2500'.repeat(20)}`
  : '\ud83c\udfeb JECRC Timetable';

const response = `${header}\n\n${formatted.join('\n\n')}`;

return [{ json: {
  phoneNumber: preprocessed.phoneNumber,
  phoneNumberId: preprocessed.phoneNumberId,
  response
}}];
